def majority_3x3(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            # Collect neighborhood
            neighborhood = []
            for di in range(-1, 2):
                for dj in range(-1, 2):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < cols:
                        neighborhood.append(grid[ni][nj])
            if 4 in neighborhood:
